import * as T from './vendor/three.module.js';
import {rng} from './generation.mjs';
import {cometEnvelope} from './effects.mjs';
export function createComets(scene,texture,seed,suns=[],horizon=null){
 const random=rng(seed^0x4ca903),range=(a,b)=>a+(b-a)*random(),pool=[];
 const vertex='varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}';
 const fragment='varying vec2 vUv;uniform vec3 color;uniform float opacity;void main(){float crossTail=pow(max(0.,1.-abs(vUv.y*2.-1.)),2.);float trail=pow(max(0.,1.-vUv.x),1.5);gl_FragColor=vec4(color*1.8,opacity*crossTail*trail);}';
 function ribbon(color){const g=new T.BufferGeometry(),positions=new Float32Array(33*6),uv=[],index=[];for(let i=0;i<=32;i++){uv.push(i/32,0,i/32,1);if(i<32){const n=i*2;index.push(n,n+1,n+2,n+1,n+3,n+2);}}g.setAttribute('position',new T.BufferAttribute(positions,3).setUsage(T.DynamicDrawUsage));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(index);const m=new T.Mesh(g,new T.ShaderMaterial({uniforms:{color:{value:new T.Color(color)},opacity:{value:0}},vertexShader:vertex,fragmentShader:fragment,transparent:true,blending:T.AdditiveBlending,depthWrite:false,side:T.DoubleSide}));m.frustumCulled=false;return m;}
 for(let i=0;i<4;i++){const group=new T.Group(),head=new T.Sprite(new T.SpriteMaterial({map:texture,color:0xc9f3ff,blending:T.AdditiveBlending,depthWrite:false})),core=new T.Sprite(new T.SpriteMaterial({map:texture,color:0xffffff,blending:T.AdditiveBlending,depthWrite:false}));head.scale.setScalar(12);core.scale.setScalar(3);const ion=ribbon(0x85ceff),dust=ribbon(0xf5d4a0);group.add(dust,ion,head,core);group.visible=false;scene.add(group);pool.push({group,head,core,ion,dust,velocity:new T.Vector3(),born:-100,life:0,length:100});}
 const forward=new T.Vector3(),right=new T.Vector3(),up=new T.Vector3(),side=new T.Vector3(),direction=new T.Vector3(),view=new T.Vector3();let next=.6,spawnCount=0;
 function spawn(time,camera){const c=pool.find(c=>time-c.born>=c.life);if(!c)return;camera.getWorldDirection(forward);right.setFromMatrixColumn(camera.matrixWorld,0);up.setFromMatrixColumn(camera.matrixWorld,1);const depth=range(260,600),sign=random()<.5?1:-1,width=depth*Math.tan(T.MathUtils.degToRad(camera.fov/2))*camera.aspect;
 c.group.position.copy(camera.position).addScaledVector(forward,depth).addScaledVector(right,-sign*width*.82).addScaledVector(up,depth*range(.07,.36));c.velocity.copy(right).multiplyScalar(sign*range(45,80)).addScaledVector(up,-range(5,17)).addScaledVector(forward,range(-5,8));c.born=time;c.life=range(11,17);c.length=range(70,145);c.group.visible=true;spawnCount++;
 }
 function drawTail(mesh,c,width,curve,opacity){const positions=mesh.geometry.attributes.position;for(let i=0;i<=32;i++){const t=i/32,w=(.18+Math.pow(t,.7)*width);for(let s=0;s<2;s++){const sign=s===0?-1:1;const bend=curve*t*t;positions.setXYZ(i*2+s,-direction.x*c.length*t+side.x*(sign*w+bend),-direction.y*c.length*t+side.y*(sign*w+bend),-direction.z*c.length*t+side.z*(sign*w+bend));}}positions.needsUpdate=true;mesh.material.uniforms.opacity.value=opacity;}
 return {update(time,dt,camera){if(time>=next){spawn(time,camera);next=time+(spawnCount===1?2.8:range(4.8,9.));}for(const c of pool){const age=time-c.born,alpha=cometEnvelope(age,c.life);c.group.visible=alpha>0&&(!horizon||c.group.position.distanceTo(horizon.position)>400);if(!c.group.visible)continue;c.group.position.addScaledVector(c.velocity,dt);if(horizon){const pull=horizon.position.clone().sub(c.group.position),distance=pull.length();if(distance<450)c.velocity.addScaledVector(pull.normalize(),Math.min(18,220000/Math.max(400,distance*distance))*dt);}const star=suns.filter(s=>!s.userData.binary).reduce((best,s)=>!best||s.position.distanceToSquared(c.group.position)<best.position.distanceToSquared(c.group.position)?s:best,null);if(star)direction.subVectors(star.position,c.group.position).normalize();else direction.copy(c.velocity).normalize();view.subVectors(camera.position,c.group.position).normalize();side.crossVectors(direction,view).normalize();if(side.lengthSq()<.01)side.setFromMatrixColumn(camera.matrixWorld,1);c.head.material.opacity=alpha;c.core.material.opacity=alpha;drawTail(c.ion,c,1.7,0,alpha*.8);direction.lerp(c.velocity.clone().normalize(),.35).normalize();drawTail(c.dust,c,5.5,12,alpha*.2);}}};
}
